style.css:
/* Chocolate Diary — Pinterest */

:root {
  --my-bg: #eee5d9;
  --my-card: #f7f1e9;
  --my-brown: #4b3025;
  --my-text: #38251d;
  --my-accent: #9b7053;
}

/* warm background */
body {
  background-color: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* brown Pinterest text */
h1, h2, h3, h4, p, span, label {
  color: var(--my-text) !important;
}

/* brown links */
a {
  color: var(--my-brown) !important;
}

/* rounded pin images */
img {
  border-radius: 12px !important;
}

/* soft search fields */
input {
  background-color: var(--my-card) !important;
  color: var(--my-text) !important;
  border-radius: 24px !important;
}

/* caramel buttons */
button {
  border-radius: 20px !important;
  color: var(--my-brown) !important;
}
